/**
 * The visible trial and its offer, as words and numbers on a screen
 * (`marketing/research/2026-10-13-trial-offers-design.md`, §1–§4).
 *
 * The server decides everything: whether there is an offer, for whom, at
 * what price and until when (`/billing/state` `offer`), and how long the
 * trial runs. This file only says it: days left, the dates, the countdown
 * in the last day, and the two prices of an offer, always together. Pure:
 * every function takes the clock, and a time zone only so the tests can pin
 * one (a screen passes none and gets the learner's own).
 *
 * Honesty rules held here, never per screen: no "was" price, no
 * percentage, no "save"; the first-period price is never written without
 * the renewal price beside it; no seconds and no ticking in a countdown.
 */
import type { ApiBillingState } from '@/api/types.js';
import { t } from '@/i18n/index.js';
import { runningTrial } from './trial.js';

const HOUR_MS = 3_600_000;
const DAY_MS = 24 * HOUR_MS;

/**
 * The last stretch before an offer closes in which the screen says the
 * time ("ends today at 18:00") rather than the date. The spec's rule
 * (§1.3, §5.3): dates until the last 24 hours, then the time, never
 * seconds. A product rule about wording, so it lives beside it.
 */
export const OFFER_LAST_HOURS = 24;

/** The one open offer for this client, as the server sent it. */
export type Offer = NonNullable<ApiBillingState['offer']>;

/** Whether Pro on this plan was bought from a store (not a trial or a gift). */
export function paidPlan(state: ApiBillingState | null): boolean {
  return (
    state?.plan === 'pro' &&
    (state.provider === 'paddle' || state.provider === 'google_play' || state.provider === 'apple')
  );
}

function instant(iso: string | undefined): Date | undefined {
  if (iso === undefined) return undefined;
  const ms = Date.parse(iso);
  return Number.isNaN(ms) ? undefined : new Date(ms);
}

/**
 * The offer, while it is open by this clock and the account has not paid.
 * The server stops sending it at `closesAt`; a page left open across that
 * moment drops it here, so nobody is shown a price that will be refused.
 */
export function openOffer(state: ApiBillingState | null, now: Date): Offer | undefined {
  const offer = state?.offer;
  if (state === null || offer === undefined || paidPlan(state)) return undefined;
  const closes = instant(offer.closesAt);
  if (closes === undefined || closes.getTime() <= now.getTime()) return undefined;
  const opens = instant(offer.opensAt);
  if (opens !== undefined && opens.getTime() > now.getTime()) return undefined;
  return offer;
}

/**
 * Whether the Plan page tells the trial's story rather than the plain plan
 * rows: a running trial, or an open offer for an account that has not paid
 * (the hours after the trial, or Pro given as days).
 */
export function tellsTrialStory(state: ApiBillingState | null, now: Date): boolean {
  if (state === null || paidPlan(state)) return false;
  return runningTrial(state, now) !== undefined || openOffer(state, now) !== undefined;
}

/** When the offer closes, or undefined for an unreadable date. */
export function offerCloses(offer: Offer): Date | undefined {
  return instant(offer.closesAt);
}

// ---------------------------------------------------------------------------
// Days and dates

/** A local calendar day as a number, in `zone` or the device's own zone. */
export function calendarDay(at: Date, zone?: string): number {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: zone,
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
  }).formatToParts(at);
  const part = (type: string): number => Number(parts.find((one) => one.type === type)?.value ?? 0);
  return Math.round(Date.UTC(part('year'), part('month') - 1, part('day')) / DAY_MS);
}

/**
 * Days left in the trial after today: 0 on its last day. `endsAt` is
 * exclusive, so the last day is the one of the last moment that is still
 * Pro, as `trialDate` reads it: a trial ending at local midnight does not
 * gain a day.
 */
export function trialDaysLeft(endsAt: Date, now: Date, zone?: string): number {
  const last = new Date(endsAt.getTime() - 1);
  return Math.max(0, calendarDay(last, zone) - calendarDay(now, zone));
}

/** "Pro trial · 9 days left", or "Pro trial · last day". */
export function trialStatus(endsAt: Date, now: Date, zone?: string): string {
  const left = trialDaysLeft(endsAt, now, zone);
  return left === 0 ? t('trial.chipLastDay') : t('trial.chipDays', { count: left });
}

/** How much of the trial has been used, 0 to 1, for the thin bar. */
export function trialUsed(startedAt: Date | undefined, endsAt: Date, now: Date): number {
  if (startedAt === undefined) return 0;
  const length = endsAt.getTime() - startedAt.getTime();
  if (length <= 0) return 1;
  return Math.min(1, Math.max(0, (now.getTime() - startedAt.getTime()) / length));
}

/** A day as a date somebody reads, with its weekday: "Sat, Oct 24". */
export function weekdayDate(at: Date, now: Date, zone?: string): string {
  const sameYear =
    new Intl.DateTimeFormat('en-US', { timeZone: zone, year: 'numeric' }).format(at) ===
    new Intl.DateTimeFormat('en-US', { timeZone: zone, year: 'numeric' }).format(now);
  return at.toLocaleDateString(undefined, {
    timeZone: zone,
    weekday: 'short',
    day: 'numeric',
    month: 'short',
    ...(sameYear ? {} : { year: 'numeric' }),
  });
}

/** A day as a short date: "Oct 24" (the year only when it is not this one). */
export function shortDate(at: Date, now: Date, zone?: string): string {
  const sameYear =
    new Intl.DateTimeFormat('en-US', { timeZone: zone, year: 'numeric' }).format(at) ===
    new Intl.DateTimeFormat('en-US', { timeZone: zone, year: 'numeric' }).format(now);
  return at.toLocaleDateString(undefined, {
    timeZone: zone,
    day: 'numeric',
    month: 'short',
    ...(sameYear ? {} : { year: 'numeric' }),
  });
}

/** The last day of an exclusive end, as a date with its weekday. */
export function lastDayOf(end: Date, now: Date, zone?: string): string {
  return weekdayDate(new Date(end.getTime() - 1), now, zone);
}

/** The time of day, hours and minutes in the reader's own style: "18:00" or "6:00 PM". */
function clock(at: Date, zone?: string): string {
  return at.toLocaleTimeString(undefined, { timeZone: zone, hour: 'numeric', minute: '2-digit' });
}

/**
 * An end as the screen says it: a date until its last 24 hours, then the
 * time ("today at 18:00", "tomorrow at 09:00", or midnight tonight for an
 * end that falls as a day ends). Never seconds; it changes when the screen
 * is drawn again, not under the reader.
 */
export type Deadline =
  | { kind: 'date'; date: string }
  | { kind: 'today'; time: string }
  | { kind: 'tomorrow'; time: string }
  | { kind: 'tonight' };

export function deadline(end: Date, now: Date, zone?: string): Deadline {
  if (end.getTime() - now.getTime() > OFFER_LAST_HOURS * HOUR_MS) {
    return { kind: 'date', date: lastDayOf(end, now, zone) };
  }
  const today = calendarDay(now, zone);
  const day = calendarDay(end, zone);
  const atMidnight = calendarDay(new Date(end.getTime() - 1), zone) !== day;
  if (atMidnight && day === today + 1) return { kind: 'tonight' };
  const time = clock(end, zone);
  return day === today ? { kind: 'today', time } : { kind: 'tomorrow', time };
}

/** The end as the object of "until": "Mon, Oct 26", "18:00 today", "midnight tonight". */
export function untilWords(end: Date, now: Date, zone?: string): string {
  const when = deadline(end, now, zone);
  switch (when.kind) {
    case 'date':
      return when.date;
    case 'today':
      return t('offer.timeToday', { time: when.time });
    case 'tomorrow':
      return t('offer.timeTomorrow', { time: when.time });
    case 'tonight':
      return t('offer.midnightTonight');
  }
}

/** Until when an offer is open, as a sentence: "Open until Mon, Oct 26." or "Ends today at 18:00." */
export function offerDeadline(closesAt: Date, now: Date, zone?: string): { soon: boolean; text: string } {
  const when = deadline(closesAt, now, zone);
  switch (when.kind) {
    case 'date':
      return { soon: false, text: t('offer.openUntil', { date: when.date }) };
    case 'today':
      return { soon: true, text: t('offer.endsToday', { time: when.time }) };
    case 'tomorrow':
      return { soon: true, text: t('offer.endsTomorrow', { time: when.time }) };
    case 'tonight':
      return { soon: true, text: t('offer.endsTonight') };
  }
}

// ---------------------------------------------------------------------------
// Money

/** How many minor units a currency has: 2 for euros, 0 for yen. Unknown is 2. */
export function minorDigits(currency: string): number {
  try {
    return (
      new Intl.NumberFormat('en', { style: 'currency', currency }).resolvedOptions().maximumFractionDigits ??
      2
    );
  } catch {
    return 2;
  }
}

/**
 * An amount in the currency's own minor units, as money: 2099 USD is
 * "$20.99", 2000 USD "$20", 2500 JPY "¥2,500". A round price reads round,
 * as `price` in state.ts does it.
 */
export function money(amountMinor: number, currency: string): string {
  const digits = minorDigits(currency);
  const major = amountMinor / 10 ** digits;
  const round = digits === 0 || amountMinor % 10 ** digits === 0;
  const options = round ? { minimumFractionDigits: 0, maximumFractionDigits: 0 } : {};
  try {
    return new Intl.NumberFormat(undefined, { style: 'currency', currency, ...options }).format(major);
  } catch {
    return `${major.toFixed(round ? 0 : digits)} ${currency}`;
  }
}

/** The two prices an offer is, written by the store when it has its own words. */
export interface OfferPrices {
  /** The first period: "$20.99 for your first year". */
  first: string;
  /** What follows: "then $29.99 a year". */
  then: string;
}

/**
 * What the store itself says the two prices are, when it says anything:
 * Google Play's pricing phases or Apple's introductory offer. Its strings
 * win over a figure formatted here.
 */
export interface StoreOfferWords {
  first?: string | undefined;
  renewal?: string | undefined;
}

/**
 * An offer's two prices as words, always together. The plan's period
 * names the unit (a yearly plan's first period is a year); `periods` says
 * how many periods the first price covers.
 */
export function offerAmounts(offer: Offer, store: StoreOfferWords = {}): { first: string; renewal: string } {
  return {
    first: nonEmpty(store.first) ?? money(offer.firstPeriod.amountMinor, offer.firstPeriod.currency),
    renewal: nonEmpty(store.renewal) ?? money(offer.renewal.amountMinor, offer.renewal.currency),
  };
}

export function offerPrices(offer: Offer, store: StoreOfferWords = {}): OfferPrices {
  const yearly = offer.planId === 'pro_yearly';
  const { first, renewal } = offerAmounts(offer, store);
  const many = offer.periods > 1;
  const firstKey = yearly
    ? many
      ? 'offer.firstYears'
      : 'offer.firstYear'
    : many
      ? 'offer.firstMonths'
      : 'offer.firstMonth';
  return {
    first: t(firstKey, { amount: first, count: offer.periods }),
    then: t(yearly ? 'offer.thenYear' : 'offer.thenMonth', { amount: renewal }),
  };
}

function nonEmpty(text: string | undefined): string | undefined {
  return text === undefined || text.trim() === '' ? undefined : text;
}

// ---------------------------------------------------------------------------
// Words per offer family

/** The families of words the app knows (`copyKey`); anything else reads plain. */
const KNOWN_COPY = ['early'] as const;
type CopyFamily = (typeof KNOWN_COPY)[number] | 'plain';

/** Which family of words an offer is spoken of in. */
export function copyFamily(offer: Offer): CopyFamily {
  return (KNOWN_COPY as readonly string[]).includes(offer.copyKey) ? (offer.copyKey as CopyFamily) : 'plain';
}

/** The offer's badge, or undefined when its family has none. */
export function offerBadge(offer: Offer): string | undefined {
  return copyFamily(offer) === 'early' ? t('offer.early.badge') : undefined;
}

/** "The early price is open until {date}." for the hero line. */
export function offerOpenLine(offer: Offer, date: string): string {
  return copyFamily(offer) === 'early'
    ? t('offer.early.openUntil', { date })
    : t('offer.plain.openUntil', { date });
}

/** "Your early price is still open until {date}." for the end card. */
export function offerStillOpenLine(offer: Offer, date: string): string {
  return copyFamily(offer) === 'early'
    ? t('offer.early.stillOpen', { date })
    : t('offer.plain.stillOpen', { date });
}

/** Where a subscription is cancelled, by the store that sells it. */
export function storeName(provider: Offer['provider'] | 'paddle' | 'google_play' | 'apple'): string {
  switch (provider) {
    case 'google_play':
      return t('offer.store.play');
    case 'apple':
      return t('offer.store.apple');
    default:
      return t('offer.store.paddle');
  }
}

/**
 * The most trial days the server adds to a first period (back
 * `app/offers/daysback.go`); this mirrors its rule only to state the
 * renewal date the server will set, never to decide anything.
 */
export const TRIAL_DAYS_BACK_MAX = 30;

/**
 * How many days the server adds to the first period when this offer is
 * bought now (`trialDaysBack`): the whole days left in the trial, rounded
 * down, at most `TRIAL_DAYS_BACK_MAX`. Zero without the flag or a running
 * trial.
 */
export function trialDaysBackAdded(
  state: ApiBillingState | null,
  offer: Offer | undefined,
  nowMs: number,
): number {
  if (offer?.trialDaysBack !== true) return 0;
  const ends = instant(state?.trial?.endsAt);
  if (ends === undefined || ends.getTime() <= nowMs) return 0;
  return Math.min(TRIAL_DAYS_BACK_MAX, Math.floor((ends.getTime() - nowMs) / DAY_MS));
}
