/**
 * An offer's two prices in the seller's own words where the seller has
 * them: Google Play's pricing phases in the Android app, Apple's
 * introductory offer in the iPhone app. On the web and the desktop, and on
 * an Android shell too old to ask Play, the server's amounts formatted
 * here. In the phone apps the server's dollars are never shown otherwise:
 * while the store has not answered, or lists no such offer, there are no
 * words, and the screen sells the plan at the store's own price instead.
 * Never a price nobody sent.
 */
import { useEffect, useState } from 'react';
import { appStoreIntroPrice } from './appstore.js';
import { offerAmounts, type Offer } from './offer.js';
import { onAndroid, onIOS, playOfferWords, type PlayOfferAnswer } from './play.js';
import { formatPrice, paidPrices, useBilling } from './state.js';

export function useOfferWords(
  offer: Offer | undefined,
): { first: string; renewal: string; fromStore?: boolean } | undefined {
  const state = useBilling((s) => s.state);
  const refs = offer?.play;
  const key = refs === undefined ? '' : `${refs.productId}/${refs.basePlanId}/${refs.offerId}`;
  // Play's answer, with the offer it was for: an answer for another offer is no answer.
  const [play, setPlay] = useState<{ key: string; answer: PlayOfferAnswer } | undefined>(undefined);

  useEffect(() => {
    if (refs === undefined || !onAndroid()) return;
    let live = true;
    void playOfferWords(refs).then((answer) => {
      if (live) setPlay({ key, answer });
    });
    return () => {
      live = false;
    };
    // The refs are read through their key: a new object with the same ids is the same offer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);

  if (offer === undefined) return undefined;
  if (onIOS()) {
    // Apple's introductory price for the product, and the plan's own price
    // (already Apple's in the iPhone app) for what follows. The server's
    // dollars never show in the iPhone app: without Apple's two strings
    // there is no offer to show there.
    const renewal = paidPrices(state).find((one) => one.id === offer.planId);
    const first =
      offer.apple === undefined
        ? undefined
        : appStoreIntroPrice(offer.apple.productId, offer.apple.promotionalOfferId);
    if (first === undefined || renewal?.display === undefined) return undefined;
    return { ...offerAmounts(offer, { first, renewal: formatPrice(renewal) }), fromStore: true };
  }
  if (onAndroid()) {
    // An offer the server sold without a Play offer to match cannot be sold here.
    if (refs === undefined) return undefined;
    const answer = play?.key === key ? play.answer : undefined;
    if (answer === undefined || answer.kind === 'none') return undefined;
    if (answer.kind === 'server') return offerAmounts(offer);
    // What follows the offer: Play's recurring phase, else the plan's own
    // price (already Play's here); never the server's dollars beside Play's.
    const renewal =
      answer.renewal ?? paidPrices(state).find((one) => one.id === offer.planId && one.display !== undefined);
    if (renewal === undefined) return undefined;
    return {
      first: answer.first,
      renewal: typeof renewal === 'string' ? renewal : formatPrice(renewal),
      fromStore: true,
    };
  }
  return offerAmounts(offer);
}
