/**
 * What the device says about motion, for the celebration pieces
 * (`Burst`, `CountUp`, `Ring`). Read when a piece first draws.
 */

/** How many confetti pieces fall, by size: enough to feel like something, few enough to stay calm. */
export const BURST_PIECES = { small: 14, burst: 18, takeover: 24 } as const;

/** Whether this device asked for less motion. */
export function prefersReducedMotion(): boolean {
  return (
    typeof window.matchMedia === 'function' && window.matchMedia('(prefers-reduced-motion: reduce)').matches
  );
}

/** Done today out of done and still due, between 0 and 1, for Today's ring. Nothing at all is 0. */
export function ringFraction(done: number, due: number): number {
  const all = Math.max(0, done) + Math.max(0, due);
  if (all <= 0) return 0;
  return Math.min(1, Math.max(0, done) / all);
}
