/**
 * The plans a selling screen offers, as the picker draws them (offer
 * presentation spec §5, uiux offers spec §2.4). Pure: the screen passes
 * the plan, the open offer and the store's own words for it.
 *
 * - Yearly first and chosen by default, monthly second.
 * - The billed-today amount is the price; the renewal is said in the same
 *   card. No monthly equivalent, no percentage, no "was" price.
 * - One badge on the screen: the offer's (Early price, a season's), or
 *   "Best value" on a yearly plan that costs less than twelve months, worked
 *   out from the two prices.
 */
import type { ApiBillingState } from '@/api/types.js';
import { getLocale, t } from '@/i18n/index.js';
import { money, type Offer } from './offer.js';
import { onIOS } from './play.js';
import { formatPrice, paidPrices } from './state.js';

export type PaidPlanId = 'pro_monthly' | 'pro_yearly';
export type Store = 'paddle' | 'google_play' | 'apple';
export type BadgeKind =
  | 'early_price'
  | 'best_value'
  | 'new_year_price'
  | 'black_friday_price'
  | 'back_to_school_price'
  | 'percent_off_first_year';

export interface PlanChoice {
  id: PaidPlanId;
  title: string;
  /** What is charged today, in the seller's words where it has them. */
  billed: string;
  /** Under the amount: "first year", "a year", "a month". */
  unit: string;
  /** The renewal or a plain note, with <b>…</b> around the amount. */
  note: string;
  badge?: BadgeKind | undefined;
  /** The open offer this choice sells, if it is one. */
  offer?: Offer | undefined;
  /** A public sale's reference price, struck before the billed amount (only when the server sent it). */
  reference?: string | undefined;
  /** What it renews at, for the disclosure (the offer's renewal, or the billed price). */
  renewal: string;
  /** How many periods the first price covers (1 for a plain plan). */
  periods: number;
}

/**
 * A public sale's computed reduction (presentation spec §5.1, owner D3),
 * only when the server sent it: a `reference` on a seasonal sale, never on
 * a personal offer, never worked out here. It is shown only beside the
 * server's own amounts in the same currency: next to a store's local price
 * (Google Play, the App Store) a dollar reference would compare two
 * different things, so there it is left out.
 */
export function saleReference(
  offer: Offer | undefined,
  storeWords = false,
): { price: string; percentOff: number } | undefined {
  const reference = offer?.reference;
  if (offer === undefined || reference === undefined || offer.creative?.kind !== 'seasonal_sale')
    return undefined;
  if (storeWords || onIOS() || reference.price.currency !== offer.firstPeriod.currency) return undefined;
  if (!Number.isInteger(reference.percentOff) || reference.percentOff < 1 || reference.percentOff > 99) {
    return undefined;
  }
  return {
    price: money(reference.price.amountMinor, reference.price.currency),
    percentOff: reference.percentOff,
  };
}

/** A badge in words; the reduction's carries its number, in the UI's digits. */
export function badgeWords(kind: BadgeKind, offer?: Offer): string {
  if (kind === 'percent_off_first_year') {
    const percent = offer?.reference?.percentOff ?? 0;
    return t('badge.percent_off_first_year', { percent: new Intl.NumberFormat(getLocale()).format(percent) });
  }
  return t(`badge.${kind}`);
}

/** What a countdown says is ending: the offer's name, or plainly for "Best value" and a reduction. */
export function countdownLabel(kind: BadgeKind | undefined): string | undefined {
  return kind === undefined || kind === 'best_value' || kind === 'percent_off_first_year'
    ? undefined
    : t(`badge.${kind}`);
}

/** The badge an offer carries: a sale's reduction, else its campaign's, else its family's. */
export function offerBadgeKind(offer: Offer): BadgeKind | undefined {
  if (saleReference(offer) !== undefined) return 'percent_off_first_year';
  const badge = offer.creative?.badge === 'percent_off_first_year' ? undefined : offer.creative?.badge;
  if (badge !== undefined) return badge;
  return offer.copyKey === 'early' ? 'early_price' : undefined;
}

/** "Best value" is true when a full yearly price is less than twelve months of the monthly one. */
export function bestValue(state: ApiBillingState | null): boolean {
  const prices = paidPrices(state);
  const yearly = prices.find((p) => p.id === 'pro_yearly');
  const monthly = prices.find((p) => p.id === 'pro_monthly');
  if (yearly === undefined || monthly?.currency !== yearly.currency) return false;
  return yearly.amountMinor < monthly.amountMinor * 12;
}

/**
 * The choices, yearly first. `offerWords` is the offer's two amounts in
 * the seller's words; without them (the iPhone app before StoreKit has the
 * offer) the offer is not shown and its plan is sold at its own price.
 */
export function planChoices(
  state: ApiBillingState | null,
  offer: Offer | undefined,
  offerWords: { first: string; renewal: string; fromStore?: boolean } | undefined,
): PlanChoice[] {
  const prices = paidPrices(state);
  const deal = offer !== undefined && offerWords !== undefined ? offer : undefined;
  const best = deal === undefined && bestValue(state);
  const choices: PlanChoice[] = [];
  for (const id of ['pro_yearly', 'pro_monthly'] as const) {
    const yearly = id === 'pro_yearly';
    const price = prices.find((p) => p.id === id);
    // The App Store's own name for the plan where it gives one (Guideline 3.1.2).
    const title = price?.title ?? (yearly ? t('pick.yearly') : t('pick.monthly'));
    if (deal?.planId === id && offerWords !== undefined) {
      const many = deal.periods > 1;
      choices.push({
        id,
        title,
        billed: offerWords.first,
        unit: yearly
          ? many
            ? t('pick.unit.firstYears', { count: deal.periods })
            : t('pick.unit.firstYear')
          : many
            ? t('pick.unit.firstMonths', { count: deal.periods })
            : t('pick.unit.firstMonth'),
        note: yearly
          ? many
            ? t('pick.note.thenYears', { amount: offerWords.renewal, count: deal.periods })
            : t('pick.note.thenYear', { amount: offerWords.renewal })
          : many
            ? t('pick.note.thenMonths', { amount: offerWords.renewal, count: deal.periods })
            : t('pick.note.thenMonth', { amount: offerWords.renewal }),
        badge: offerBadgeKind(deal),
        offer: deal,
        reference: saleReference(deal, offerWords.fromStore === true)?.price,
        renewal: offerWords.renewal,
        periods: deal.periods,
      });
      continue;
    }
    if (price === undefined) continue;
    const amount = formatPrice(price);
    choices.push({
      id,
      title,
      billed: amount,
      unit: yearly ? t('pick.unit.year') : t('pick.unit.month'),
      note: yearly ? t('pick.note.yearly') : t('pick.note.monthly'),
      badge: yearly && best ? 'best_value' : undefined,
      renewal: amount,
      periods: 1,
    });
  }
  return choices;
}

/** The button's words, with the amount billed today: "Keep Pro · $20.99 today". */
export function buyLabel(choice: PlanChoice, trial: boolean): string {
  if (choice.id === 'pro_monthly' && choice.offer === undefined) {
    return t(trial ? 'buy.keepMonthly' : 'buy.getMonthly', { amount: choice.billed });
  }
  return t(trial ? 'buy.keep' : 'buy.get', { amount: choice.billed });
}

/** The legal sentence for the chosen plan, with where to cancel, in the seller's terms. */
export function disclosure(choice: PlanChoice, store: Store): string {
  let terms: string;
  if (choice.offer !== undefined) {
    terms =
      choice.id === 'pro_yearly'
        ? choice.periods > 1
          ? t('disclose.yearlyOfferYears', {
              first: choice.billed,
              renewal: choice.renewal,
              count: choice.periods,
            })
          : t('disclose.yearlyOffer', { first: choice.billed, renewal: choice.renewal })
        : choice.periods > 1
          ? t('disclose.monthlyOffer', {
              first: choice.billed,
              renewal: choice.renewal,
              count: choice.periods,
            })
          : t('disclose.monthlyOfferOne', { first: choice.billed, renewal: choice.renewal });
  } else {
    terms = t(choice.id === 'pro_yearly' ? 'disclose.yearly' : 'disclose.monthly', { amount: choice.billed });
  }
  return `${terms} ${t(`disclose.cancel.${store}`)}`;
}

/** The trust row: nothing is charged by doing nothing (trial), and who takes the payment. */
export function trustLine(trial: boolean, store: Store): string {
  return `${t(trial ? 'trust.trial' : 'trust.paid')} · ${t(`trust.${store}`)}`;
}
