/**
 * The offer's funnel (`POST /billing/offers/{id}/events`): shown, opened
 * and dismissed, by surface. Fire and forget: a failure is ignored, and the
 * server counts each at most once a day per surface, so this keeps only a
 * small guard against sending the same one many times in one run.
 */
import { billing as billingApi } from '@/api/endpoints.js';
import type { ApiOfferEventInput } from '@/api/types.js';

const sent = new Set<string>();

export function sendOfferEvent(
  offerId: string,
  event: ApiOfferEventInput['event'],
  surface: ApiOfferEventInput['surface'],
  extra: Omit<ApiOfferEventInput, 'event' | 'surface'> = {},
): void {
  const key = `${offerId}:${event}:${surface}:${new Date().toDateString()}`;
  // Opening the Plan page is counted each time it is chosen; the others
  // once a day is all the server keeps anyway.
  if (event !== 'opened' && sent.has(key)) return;
  sent.add(key);
  try {
    void billingApi.offerEvent(offerId, { event, surface, ...extra }).catch(() => undefined);
  } catch {
    // Nothing a learner should ever hear about.
  }
}

/** For tests: forget what was sent. */
export function forgetOfferEvents(): void {
  sent.clear();
}
